package com.lianxibu.site.repository.jobs;
import com.lianxibu.site.domain.jobs.CollectorMemoryFacts;import com.lianxibu.site.domain.protocol.*;import java.time.*;import java.time.temporal.ChronoUnit;import java.util.*;import javax.sql.DataSource;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.transaction.*;import org.springframework.transaction.support.*;
/** Complete current authority and exact original memory history inside one owned native read-only RR. */
public final class JdbcCollectorMemoryFacts implements CollectorMemoryFacts.Api {
 private final JdbcTemplate sql;private final JdbcCollectorHostMemory memory;private final TransactionTemplate reads;private final Clock clock;private final long maximum;
 private static final Set<String> PERMISSIONS=Set.of("config:read","run:claim","run:read","run:write","observation:write","heartbeat:write","probe:claim","probe:write");
 public JdbcCollectorMemoryFacts(DataSource source,PlatformTransactionManager tx,Clock clock,long expectedMaximumBytes){sql=new JdbcTemplate(Objects.requireNonNull(source));memory=new JdbcCollectorHostMemory(source);this.clock=Objects.requireNonNull(clock);if(expectedMaximumBytes<1||expectedMaximumBytes>CanonicalJson.MAX_SAFE_INTEGER)throw invalid();maximum=expectedMaximumBytes;reads=new TransactionTemplate(Objects.requireNonNull(tx));reads.setReadOnly(true);reads.setIsolationLevel(TransactionDefinition.ISOLATION_REPEATABLE_READ);reads.setTimeout(10);}
 @Override public CollectorMemoryFacts.Evidence read(String node){if(TransactionSynchronizationManager.isActualTransactionActive())throw invalid();try{return reads.execute(status->acquire(node));}catch(RuntimeException unavailable){return null;}}
 private record Node(long revision,boolean enabled){}
 private CollectorMemoryFacts.Evidence acquire(String node){WireValues.id(node,false);var nodes=sql.query("SELECT config_revision,enabled,CASE WHEN OCTET_LENGTH(allowed_source_ids) BETWEEN 1 AND 65536 THEN allowed_source_ids ELSE NULL END,CASE WHEN OCTET_LENGTH(permissions_json) BETWEEN 1 AND 2048 THEN permissions_json ELSE NULL END FROM collector_nodes WHERE id=?",(r,n)->{if(r.getObject(1)==null||r.getObject(2)==null)throw invalid();long revision=r.getLong(1);int enabled=r.getInt(2);if(revision<1||revision>CanonicalJson.MAX_SAFE_INTEGER||enabled<0||enabled>1)throw invalid();ids(r.getString(3),1000,false);var permissions=ids(r.getString(4),8,true);if(enabled==1&&!permissions.contains("heartbeat:write"))throw invalid();return new Node(revision,enabled==1);},node);if(nodes.size()!=1)throw invalid();var current=nodes.getFirst();var history=memory.latest(node,current.revision());CollectorMemoryFacts.Snapshot sample=null;long revision=0;Instant received=null;if(history!=null){var entry=history.latest();var value=entry.input().sample();sample=new CollectorMemoryFacts.Snapshot(value.captureEpoch(),value.processIdentity(),value.captureStartedAt(),value.sequence(),value.pid(),value.observedAt(),value.rssBytes(),value.cgroupEpoch(),value.maximumBytes(),value.oomEvents(),value.oomKills());received=entry.receivedAt();revision=history.revision();}var read=clock.instant().truncatedTo(ChronoUnit.MICROS);if(Thread.currentThread().isInterrupted())throw invalid();return new CollectorMemoryFacts.Evidence(node,current.revision(),current.enabled(),maximum,revision,sample,received,read);}
 private static List<String> ids(String raw,int limit,boolean permission){if(raw==null)throw invalid();var root=CanonicalJson.parse(raw);if(!root.isArray()||root.size()>limit)throw invalid();var result=new ArrayList<String>();for(var item:root){String id=WireValues.text(item);if(permission){if(!PERMISSIONS.contains(id))throw invalid();}else WireValues.id(id,true);if(result.contains(id))throw invalid();result.add(id);}return List.copyOf(result);}
 private static IllegalStateException invalid(){return new IllegalStateException("current native collector memory facts unavailable");}
}
